CREATE TABLE public.wilayah_kerja (nama text PRIMARY KEY, urutan int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.driver (nama text PRIMARY KEY, wilayah text NOT NULL DEFAULT '', urutan int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.kendaraan (nopol text PRIMARY KEY, merk text NOT NULL DEFAULT '', driver text NOT NULL DEFAULT '', area text NOT NULL DEFAULT '', admin text NOT NULL DEFAULT '', odo numeric, kml numeric, status text NOT NULL DEFAULT 'Tersedia', urutan int NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.app_users (username text PRIMARY KEY, nama text NOT NULL, bidang text NOT NULL DEFAULT '', password text NOT NULL, role text NOT NULL DEFAULT 'Security', urutan int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.app_sessions (token text PRIMARY KEY, username text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.trips (id bigint PRIMARY KEY, tipe text NOT NULL DEFAULT 'dinas', nopol text NOT NULL, driver text NOT NULL DEFAULT '', tujuan text NOT NULL DEFAULT '', lokasi text, pengguna text, bidang text, satpam_out text NOT NULL DEFAULT '', out_at bigint NOT NULL, odo_out numeric NOT NULL DEFAULT 0, foto_odo_out text, foto_out text[] NOT NULL DEFAULT '{}', satpam_in text, in_at bigint, odo_in numeric, foto_odo_in text, foto_in text[], kondisi text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX trips_out_at_idx ON public.trips(out_at DESC);
GRANT ALL ON public.wilayah_kerja, public.driver, public.kendaraan, public.app_users, public.app_sessions, public.trips TO service_role;
ALTER TABLE public.wilayah_kerja ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.driver ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kendaraan ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.trips ENABLE ROW LEVEL SECURITY;
